    const bx = B.length === 3 ? [96, 200, 304] : B.length === 2 ? [140, 260] : [200], bw = { heat: Math.min(heat, n.house), ww: Math.min(ww, n.house), car: car ? Math.min(car.w, n.house) : 0 };
