      pv2: ["balcony", nm[1], "#fbbf24", [[per, kwh(ok ? sum.pvb : null)], ["Anteil an Solar", ok && sum.pv > 0 ? Math.round(sum.pvb / sum.pv * 100) + " %" : "–"], ["jetzt", wfmt(n.pvb || 0)]]],
