    if (live) return { live: true, pv: n.pva, pvb: n.pvb, has2: n.pvb != null, exp: n.exp, imp: n.imp, bc: n.bc, dis: n.dis, hasBat: n.hasBat, soc: n.soc, car: car ? car.w : null, hasCar: !!car };
