    let bc = 0, dis = 0; if (n.hasBat && this._enH && this._enH.res) { const t = this._enBk().reduce((a, y) => ({ c: a.c + y.bchg, d: a.d + y.bdis }), { c: 0, d: 0 }); bc = t.c; dis = t.d; }
