    const h = r.htr, kwh = Number(h.heute_kwh) || 0, days = Object.keys(h.verlauf || {}).length, line = (l, v) => `<div class="of"><div class="ol"><b>${l}</b></div><div class="oc"><b>${v}</b></div></div>`;
