    if (k === "h") return pr.filter((_, i) => i % 4 === 0).map((v, i) => `<rect x="${3 + i * 19.5}" y="${42 - v}" width="16" height="${v}" rx="2" fill="#f59e0b"/>`).join("");
    if (k === "q") return pr.map((v, i) => `<rect x="${3 + i * 4.9}" y="${42 - v}" width="3.6" height="${v}" rx="1" fill="#f59e0b"/>`).join("");
