      + ` C${peak + 40} ${roof + 6} ${aTop - 22} ${roof + 8} ${aTop - 4} ${roof + 12} C${aTop + 20} ${roof + 18} ${cx - 28} ${belt - 8} ${cx - 12} ${belt} Z`;
