      <path d="M${x1 - 42} ${nose + 4} C${x1 - 24} ${nose + 4} ${x1 - 8} ${nose + 7} ${x1 - 2} ${nose + 12}" fill="none" stroke="#bfe3ff" stroke-width="6" stroke-linecap="round" opacity="${o.night ? .85 : .3}" filter="url(#${u}gw)"/>
