    if (a === "wbvpdf") { const S = this._evSt ? this._evSt() : { at: new Date() }, t = new Date(S.at); this._modal = { type: "wbpdf", y: t.getFullYear(), m: t.getMonth(), f: "all" }; this._renderModal(); return; }
