    const R = this._wbPdfRows(m), MON = ["Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August", "September", "Oktober", "November", "Dezember"], f2 = (v) => Number(v).toFixed(2).replace(".", ",");
