      const sub = [T.n, d.ent ? esc(this._wzName(d.ent)) : `<span class="gsdw">kein Sensor</span>`, w != null ? `${run ? "läuft" : "jetzt"} ${wf(w)}` : ""].filter(Boolean).join(" · ");
