      const sub = p.unavailable ? "Kein Standort" : p.home ? `Zu Hause${since ? ` seit ${since}` : ""}` : p.dist != null ? `Unterwegs, ${dist(p.dist)} entfernt` : (p.state && p.state !== "not_home" ? esc(p.state) : "Unterwegs");
