    const hd = { wetter: "weather", personen: "people", alarm: "shield", solar: "pvRoof", batterie: "battery", auto: "car", fenster: "windowOpen", muell: "bin", warmwasser: "boiler", preis: "price", hinweise: "" }[x.id];
