    const leg = mix.tot ? EF_MIX.filter(([k]) => mix[k] > 0).map(([k, l, col]) => `<span style="color:${col}">${Math.round(mix[k] / mix.tot * 100)} % ${l}</span>`).join(" · ") : `<span>Gerade fließt kein Strom ins Haus</span>`;
