    const arrow = (x) => (x.nd ? "! keine Daten" : !x.on ? "– ruht" : x.w < 0 ? "↓ ins Haus" : x.src ? "↑ " + this._efxSub(x) : "↑ " + (x.n.bottom_label || "läuft"));
