      tiles += tx(x + w / 2, y + h * (hub ? .9 : .8), Math.max(11, w * .1), 800, on || hub ? col.tx : col.mu, val) + tx(x + w / 2, y + h * (hub ? 1.03 : .93), Math.max(9, w * .07), 600, hub ? col.mu : c, n.name);
