    en: { kacheln: "Kennzahlen", fluss: "Energiefluss", verlauf: "Verlauf", verteilung: "Verteilung", kosten: "Kosten und Vorteil", gas: "Gas", spar: "Sparschwein", heizung: "Heizung", hinweise: "Hinweise" },
    sf: { kacheln: "Kennzahlen", zustand: "Abfahrt-Prüfung", verlauf: "Letzte 30 Tage", ereignisse: "Ereignisse", naechstes: "Als Nächstes", melder: "Melder" },
    gs: { kacheln: "Kennzahlen", geraete: "Geräte", fenster: "Startfenster", verlauf: "Verlauf nach Quelle", jahr: "Dein Jahr" },
