    if (a && a.azimuth != null && a.elevation != null) return { az: Number(a.azimuth), el: Number(a.elevation), t: now, src: "sun.sun" };
    if (isFinite(lat) && isFinite(lon)) return { ...this._grSunPos(now, lat, lon), t: now, src: "berechnet" };
