    const rows = night ? C.tm : C.rows, P = rows.filter((x) => x[1] > .01), h0 = P.length ? P[0][0] : 7, h1 = P.length ? P[P.length - 1][0] + 1 : 17, span = Math.max(1, h1 - h0);
