    const dc = (st && st.attributes.device_class) || "";
    if (["temperature", "humidity"].includes(dc) && /thermostat|trv|ventil|heizkörper/i.test(`${this._wzName(e)} ${A.devName}`)) { s -= 14; why.push("misst am Heizkörper"); }
