    const cmp = d != null && isFinite(d) ? `<span class="tcmp ${d === 0 ? "" : d > 0 ? "dn" : "up"}">${d > 0 ? "▲" : d < 0 ? "▼" : "="} ${Math.abs(d)} %</span> ${cl}` : "";
    const f = (v) => num(v, v >= 100 ? 0 : v >= 10 ? 1 : 2);
