      const ph = (k) => (y == null ? null : k === "abs" ? c.abschlag : c[k]), val = (k) => (y == null ? (k === "abs" ? c.abschlag || "" : c[k] || (k === "price" || k === "grund" ? c[k] : "")) : o[k]);
