    if (a === "engasy") { const YO = (this._gasYo = this._gasYo || {}), y = b.dataset.k, cy = this._gasBy(Date.now()); YO[y] = !(YO[y] != null ? YO[y] : +y === cy); this._renderModal(); return true; }
